# name: cell_unanimity_rate
# description: Fraction of (number_set, target) cells with >=5 responses where all responses agree (all yes or all no); observed above null_mean means people respond more deterministically/consistently per stimulus than the model's graded p_yes predicts (model too noisy), below means the model is too deterministic.
def test_statistic(df):
    g = df.groupby(["number_set", "target"])["rating"].agg(["size", "mean"])
    g = g[g["size"] >= 5]
    if len(g) == 0:
        return 0.0
    m = g["mean"].to_numpy()
    return float(((m == 0) | (m == 1)).mean())

# name: example_target_yes_rate
# description: Yes rate on trials whose target is one of the shown examples; observed below null_mean means the model over-predicts endorsing the examples themselves (people are less at ceiling), above means it under-predicts.
def test_statistic(df):
    ex = df["number_set"].astype(str).str.split(",", expand=True).apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)
    t = df["target"].astype(int).to_numpy()[:, None]
    is_ex = (ex == t).any(axis=1)
    if is_ex.sum() == 0:
        return 0.0
    return float(df["rating"].to_numpy()[is_ex].mean())
